
#
# Solver for an ECDSA/AES crypto challenge.
#
# Dependencies:
# pip install pwntools pycryptodomex ecdsa
#
# The challenge has two parts:
# 1. Authentication: We need to provide a valid ECDSA signature for a message
#    we can choose. We don't know the private key, but we know the public key.
#    This can be bypassed using a standard signature forgery technique where we
#    craft the signature and the message hash simultaneously.
#
# 2. Decryption: The flag is encrypted 100,000 times with AES-ECB. The keys for
#    each round are generated by Python's `random` module, which is seeded with
#    a 32-bit ECDSA private key. This private key is used to sign a message,
#    and we are given the message and the signature.
#
# The main vulnerability is the 32-bit private key. A simple brute-force
# (checking all 2^32 keys) would be too slow. Instead, we can use the provided
# signature to recover the private key much more efficiently.
#
# The ECDSA signature equation is `s*k = z + r*d (mod n)`, where `d` is the private
# key. We can rearrange this to solve for the public key `P = d*G`:
# `P = d*G = (r^-1 * (s*kG - z*G))`.
#
# We don't know the nonce `k`, but we know `r = (kG).x`. This means there are two
# possible points for `kG` on the curve. We can calculate both possible target
# public keys (`T1`, `T2`) that correspond to our private key `d`.
#
# Then, we can use the Baby-Step Giant-Step (BSGS) algorithm to find `d` in
# O(sqrt(2^32)) = O(2^16) time, which is very fast. Once `d` is found, we can
# regenerate the AES keys and decrypt the flag.
#

import hashlib
import random
from ecdsa import SECP256k1, VerifyingKey, SigningKey
from ecdsa.ellipticcurve import Point
from ecdsa.util import sigdecode_der
from ecdsa.numbertheory import inverse_mod
from Crypto.Cipher import AES
from Crypto.Util.Padding import unpad
from pwn import remote, context, log

# --- Configuration ---
HOST = "103.160.212.3"
PORT = 5000
context.log_level = 'info'

# --- ECDSA Curve Parameters ---
CURVE = SECP256k1
G = CURVE.generator
N = CURVE.order
P_FIELD = CURVE.curve.p()


def solve_auth(r):
    """
    Bypasses the initial ECDSA verification using a signature forgery attack.
    We craft a signature (r, s) and a message hash (msg) that will be valid
    for the server's public key.
    The trick is to choose R = uG + vP, then set:
    r = R.x
    s = r * v^-1 (mod n)
    msg_hash = s * u (mod n)
    This construction guarantees the verification equation holds.
    """
    r.recvuntil(b"pubkey.x =  ")
    px = int(r.recvline().strip())
    r.recvuntil(b"pubkey.y =  ")
    py = int(r.recvline().strip())
    
    log.info("Received public key for auth.")
    log.info(f"px = {px}")
    log.info(f"py = {py}")

    public_point = Point(CURVE.curve, px, py)

    # Choose arbitrary u and v for the forgery
    u = 2
    v = 3
    
    # R = u*G + v*P
    R = u * G + v * public_point
    
    forge_r = R.x()
    v_inv = inverse_mod(v, N)
    forge_s = (forge_r * v_inv) % N
    forge_msg = (forge_s * u) % N

    log.info("Sending forged signature and message...")
    r.sendlineafter(b"message = ", hex(forge_msg)[2:].encode())
    r.sendlineafter(b"r = ", hex(forge_r)[2:].encode())
    r.sendlineafter(b"s = ", hex(forge_s)[2:].encode())
    
    response = r.recvline()
    if b"Verify Succesfull" in response:
        log.success("Authentication bypass successful!")
    else:
        log.error("Authentication failed.")
        exit(1)


def modular_sqrt(a, p):
    """
    Computes the modular square root of a modulo p.
    This simplified version works because for SECP256k1, p % 4 == 3.
    """
    if pow(a, (p - 1) // 2, p) != 1:
        return None # No square root
    return pow(a, (p + 1) // 4, p)


def recover_private_key(message, signature_der):
    """
    Recovers the 32-bit private key using the Baby-Step Giant-Step algorithm.
    This version corrects a bug that caused a crash when negating the point at infinity.
    """
    log.info("Attempting to recover the 32-bit private key...")
    
    # 1. Parse signature and hash the message
    r_sig, s_sig = sigdecode_der(signature_der, N)
    z = int.from_bytes(hashlib.sha256(message).digest(), 'big')

    # 2. Find the two possible points for kG from r
    alpha = (pow(r_sig, 3, P_FIELD) + 7) % P_FIELD
    y = modular_sqrt(alpha, P_FIELD)
    if y is None:
        log.error("Could not compute modular square root. r is not a quadratic residue.")
        return None
        
    R1 = Point(CURVE.curve, r_sig, y)
    R2 = Point(CURVE.curve, r_sig, -y % P_FIELD)
    
    # 3. Calculate the two possible target public keys (T = d*G)
    r_inv = inverse_mod(r_sig, N)
    s_r_inv = (s_sig * r_inv) % N
    neg_z_r_inv = (-(z * r_inv)) % N
    
    T1 = s_r_inv * R1 + neg_z_r_inv * G
    T2 = s_r_inv * R2 + neg_z_r_inv * G
    log.info("Calculated two possible target public keys.")

    # 4. Baby-Step Giant-Step (BSGS)
    m = 1 << 16  # sqrt(2^32)
    baby_steps = {}
    
    log.info(f"Calculating {m-1} baby steps (for d0 > 0)...")
    point = G
    for d0 in range(1, m):
        baby_steps[(point.x(), point.y())] = d0
        point += G
    
    log.info("Searching with giant steps...")
    mG = m * G
    
    # Loop for d1 from 0 to m-1
    for d1 in range(m):
        # This is the point d1*m*G
        giant_step_point = d1 * mG
        
        # First, check the d0=0 case (where priv_key is a multiple of m)
        priv_key_candidate = d1 * m
        if priv_key_candidate != 0:
            if T1 == giant_step_point:
                if SigningKey.from_secret_exponent(priv_key_candidate, curve=CURVE).get_verifying_key().pubkey.point == T1:
                    log.success(f"Private key found: {priv_key_candidate}")
                    return priv_key_candidate
            if T2 == giant_step_point:
                if SigningKey.from_secret_exponent(priv_key_candidate, curve=CURVE).get_verifying_key().pubkey.point == T2:
                    log.success(f"Private key found: {priv_key_candidate}")
                    return priv_key_candidate

        # Now, check the d0 > 0 cases by looking up T - d1*m*G in the baby_steps table
        # FIX: Handle the point at infinity (when d1=0) before negation.
        # The PointJacobi object for infinity has x=None, causing `__neg__` to fail.
        if giant_step_point.x() is None:
            # If giant_step_point is the point at infinity, subtracting it is a no-op.
            target1 = T1
            target2 = T2
        else:
            neg_giant_step_point = -giant_step_point
            target1 = T1 + neg_giant_step_point
            target2 = T2 + neg_giant_step_point
        
        # Check against first target key
        target1_coords = (target1.x(), target1.y())
        if target1_coords in baby_steps:
            d0 = baby_steps[target1_coords]
            priv_key_candidate = d1 * m + d0
            if SigningKey.from_secret_exponent(priv_key_candidate, curve=CURVE).get_verifying_key().pubkey.point == T1:
                log.success(f"Private key found: {priv_key_candidate}")
                return priv_key_candidate

        # Check against second target key
        target2_coords = (target2.x(), target2.y())
        if target2_coords in baby_steps:
            d0 = baby_steps[target2_coords]
            priv_key_candidate = d1 * m + d0
            if SigningKey.from_secret_exponent(priv_key_candidate, curve=CURVE).get_verifying_key().pubkey.point == T2:
                log.success(f"Private key found: {priv_key_candidate}")
                return priv_key_candidate
        
    log.error("BSGS failed. Private key not found.")
    return None


def decrypt_flag(priv_key, ct):
    """
    Regenerates the AES keys using the found private key and decrypts the ciphertext.
    """
    log.info("Decrypting ciphertext with the recovered key...")
    
    # 1. Seed the PRNG and generate the 100,000 AES keys
    random.seed(priv_key)
    aes_keys = [random.randbytes(32) for _ in range(100000)]
    
    # 2. Decrypt in reverse order
    decrypted_ct = ct
    for key in reversed(aes_keys):
        cipher = AES.new(key, AES.MODE_ECB)
        decrypted_ct = cipher.decrypt(decrypted_ct)
        
    # 3. Unpad and reveal the flag
    try:
        flag = unpad(decrypted_ct, AES.block_size)
        log.success(f"FLAG: {flag.decode()}")
    except ValueError as e:
        log.error(f"Failed to unpad the flag: {e}")
        log.info(f"Raw decrypted data: {decrypted_ct.hex()}")


def main():
    """
    Main function to run the solver.
    """
    try:
        conn = remote(HOST, PORT)
        
        # Part 1: Bypass authentication
        solve_auth(conn)
        
        # Part 2: Receive data for decryption
        conn.recvuntil(b"msg =  ")
        message = bytes.fromhex(conn.recvline().strip().decode())
        conn.recvuntil(b"signature =  ")
        signature_der = bytes.fromhex(conn.recvline().strip().decode())
        conn.recvuntil(b"ct =  ")
        ct = bytes.fromhex(conn.recvline().strip().decode())
        
        log.info("Received data for decryption phase.")
        
        # Part 3: Recover the key and decrypt
        priv_key = recover_private_key(message, signature_der)
        
        if priv_key is not None:
            decrypt_flag(priv_key, ct)
            
        conn.close()

    except Exception as e:
        log.error(f"An error occurred: {e}", exc_info=True)


if __name__ == "__main__":
    main()
